INSTRUCTIONS={'neutral':'Read the context carefully.','mention_x':'The topic word is {x}.','think_x':'Think about {x}.','avoid_x':'Do not think about {x}.','think_y':'Think about {y}.'}
TRAIN_FRAMES=['The description concerns {s}.','Consider {s}.','The subject is {s}.','Here is the description: {s}.','This text describes {s}.']
EVAL_FRAMES=['What is described here is {s}.','The item under discussion is {s}.','One can describe the subject as {s}.','The following is being described: {s}.']
UNRELATED=['The meeting begins after lunch.','A password must remain private.','The discussion continued for an hour.','The weather forecast changed overnight.','The report contains several sections.','The payment was approved yesterday.','An agreement requires both signatures.','The deadline has been extended.','A new policy takes effect next week.','The answer depends on the assumptions.','The calculation uses a smaller number.','The paragraph explains the procedure.','A decision will be announced tomorrow.','The problem has more than one solution.','The contract expires at the end of the month.','The lecture covers an unfamiliar topic.','A software update finished successfully.','The conversation moved to another topic.','The instructions were translated into another language.','The available evidence is incomplete.']
def prompt(instruction,text):return f'Instruction: {instruction}\n\nContext:\n{text}\n\nGive one short response about the context.'
def write(name,rows):
 with (H/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]),lineterminator='\n');w.writeheader();w.writerows(rows)
def main():
 assert len(PAIRS)==20 and len(FACTS)==40 and all(len(v)==11 for v in FACTS.values())
 train=[];evaluation=[]
 for concept,facts in FACTS.items():
  for family,s in enumerate(facts[:6]):
   for variant,frame in enumerate(TRAIN_FRAMES):
    text=frame.format(s=s);train.append(dict(item_id=f'train_{concept}_{family}_{variant}',concept=concept,family=f'{concept}_train_{family}',family_index=family,variant=variant,text=text,prompt=prompt(INSTRUCTIONS['neutral'],text)))
  for family,s in enumerate(facts[6:]):
   for variant,frame in enumerate(EVAL_FRAMES):evaluation.append(dict(concept=concept,family=f'{concept}_eval_{family}',variant=variant,text=frame.format(s=s)))
 design=[]
 for x,y in PAIRS.items():
  cues=[dict(cue_kind='x' if r['concept']==x else 'y',cue_id=f"{r['family']}_{r['variant']}",family=r['family'],text=r['text']) for r in evaluation if r['concept'] in [x,y]]
  cues += [dict(cue_kind='unrelated',cue_id=f'unrelated_{i}',family=f'unrelated_{i}',text=s) for i,s in enumerate(UNRELATED)]
  cues += [dict(cue_kind='empty',cue_id='empty',family='empty',text='[No descriptive context.]')]
  for r in cues:
   for condition,template in INSTRUCTIONS.items():design.append(dict(item_id=f"{x}__{r['cue_id']}__{condition}",pair=x,comparison=y,**r,condition=condition,prompt=prompt(template.format(x=x,y=y),r['text'])))
 write('training.csv',train);write('design.csv',design)
 cfg=dict(model='microsoft/Phi-3.5-mini-instruct',revision='2fe192450127e6a83f7441aef6e3ca586c338b77',system='You are a helpful assistant.',expected_depth=32,layers=[31],positions=['context_end','assistant_start'],primary_layer=31,primary_position='assistant_start',pairs=PAIRS,conditions=list(INSTRUCTIONS),C=0.1,shuffle_repeats=100,seed=42,probe_auc_min=0.8,fit_repeats=5,training_n=len(train),design_n=len(design),unique_n=len(set(r['prompt'] for r in train+design)),interpretation='Exploratory calibration, no causal claim. Five evaluation families per concept, four wrappers each; wrappers and five fits are not independent trials.')
 (H/'config.json').write_text(json.dumps(cfg,indent=2)+'\n')
 (H/'sources.json').write_text(json.dumps({'stimulus_authoring':'Assistant-authored features, no independent human validation. Six train and five evaluation families per concept, disjoint wrapper sets; lexical and semantic overlap remains. Original three concept pairs retained, original stimulus wording is not reused.','prepare_sha256':hashlib.sha256((H/'prepare.py').read_bytes()).hexdigest()},indent=2)+'\n')
 print({k:cfg[k] for k in ['training_n','design_n','unique_n']})
if __name__=='__main__':main()
